/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the overall TSIG records creation
/// Was previously defined in class\METTMSEngineSalesOrderProccess\createTMSShipmentItemGroup
/// </summary>
internal final class METTMSShipmentItemGroupHelper
{
    METTMSEngineSalesOrderProccessLinesTmp  processLinesTmp;
    METTMSShipmentOrderIdentifier           tmsShipmentOrderIdentifier;
    boolean                                 isToteCustomer;
    InventLocationId                        headerInventLocationId;
    boolean                                 hasCCR;

}

Method.Source:
// TODO when using CCR data, ensure that where any repacks that contain items from multiple SO-s, the CCR “TOTE ID” (container) is only calculated once.
// Need a mecanism for CCR to save Tote IDs that can be used in different SOs to avoid counting it twice 
// e.g. 6004293661 already counted as CCR data: Unique TOTE / Repack IDs by Sales Order for SO0001, do not count it a second time for SO0003
// Might have to save the Tote/Repack ID in a set in METTMSShipmentItemGroupUOM and then pass it back to METTMSEngineSalesOrderProccess for the next SO process

/// <summary>
/// New method
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
void new(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    processLinesTmp            = _processLinesTmp;
    tmsShipmentOrderIdentifier = _tmsShipmentOrderIdentifier;
    isToteCustomer             = _isToteCustomer;
    headerInventLocationId     = _headerInventLocationId;
    hasCCR                     = _hasCCR;
}

/// <summary>
/// Constructs a new TMS engine lines temp builder.
/// </summary>
/// <param name = "_processLinesTmp">Temporary TMS calculation table</param>
/// <param name = "_tmsShipmentOrderIdentifier">TSO identifier</param>
/// <param name = "_isToteCustomer">Customer uses totes</param>
/// <param name = "_headerInventLocationId">Header warehouse</param>
/// <param name = "_hasCCR">If any of the lines on the SO have a warehouse with SuppWhsHasCCR = Yes</param>
/// <returns>An instance of <c>METTMSEngineLinesTmpBuilder</c></returns>
public static METTMSShipmentItemGroupHelper construct(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp, METTMSShipmentOrderIdentifier _tmsShipmentOrderIdentifier, boolean _isToteCustomer, InventLocationId _headerInventLocationId, boolean _hasCCR)
{
    return new METTMSShipmentItemGroupHelper(_processLinesTmp, _tmsShipmentOrderIdentifier, _isToteCustomer, _headerInventLocationId, _hasCCR);
}

/// <summary>
/// Create the TSIG records
/// Was previously defined in class\METTMSEngineSalesOrderProccess\createTMSShipmentItemGroup
/// </summary>
/// <returns>True if all TSIG records creation is successulf; otherwise, false.</returns>
public boolean create()
{
    METTMSEngineSalesOrderProccessLinesTmp  processLinesGroup;
    boolean TSIGCreated = true;

    processLinesGroup.linkPhysicalTableInstance(processLinesTmp);

    while select sum(CaseQty_CaseLines),
                sum(RepackCountSecurity),
                sum(RepackCountNonSecurity),
                sum(LineWeight_CaseLines),
                sum(LineWeight_BrokenCaseSecurity),
                sum(LineWeight_BrokenCaseNonSecurity),
                sum(LineVolume_CaseLines),
                sum(LineVolume_BrokenCaseSecurity),
                sum(LineVolume_BrokenCaseNonSecurity),
                sum(SalesQty)
    from processLinesGroup
        group by LineCommodity
    {
        if (!isToteCustomer && (processLinesGroup.CaseQty_CaseLines + processLinesGroup.RepackCountSecurity + processLinesGroup.RepackCountNonSecurity) > 0
            || processLinesGroup.CaseQty_CaseLines > 0)
        {
            this.createTMSShipmentItemGroupByUOM(METConstants::unitCSE, processLinesTmp, processLinesGroup);
        }

        if (isToteCustomer && (processLinesGroup.RepackCountSecurity + processLinesGroup.RepackCountNonSecurity)>0)
        {
            this.createTMSShipmentItemGroupByUOM(METConstants::unitTOT, processLinesTmp, processLinesGroup);
        }

    }

    while select sum(CaseQty_CaseLines),
                sum(RepackCountSecurity),
                sum(RepackCountNonSecurity),
                sum(LineWeight_CaseLines),
                sum(LineWeight_BrokenCaseSecurity),
                sum(LineWeight_BrokenCaseNonSecurity),
                sum(LineVolume_CaseLines),
                sum(LineVolume_BrokenCaseSecurity),
                sum(LineVolume_BrokenCaseNonSecurity),
                sum(SalesQty)
    from processLinesGroup
        group by LineCommodity, IsKegItem
        where processLinesGroup.IsKegItem == NoYes::No
    {
        this.createTMSShipmentItemGroupByUOM(METConstants::unitPAL, processLinesTmp, processLinesGroup);
    }

    while select sum(SalesQty),
                sum(CaseQty_CaseLines),
                sum(RepackCountSecurity),
                sum(RepackCountNonSecurity),
                sum(LineWeight_CaseLines),
                sum(LineWeight_BrokenCaseSecurity),
                sum(LineWeight_BrokenCaseNonSecurity),
                sum(LineVolume_CaseLines),
                sum(LineVolume_BrokenCaseSecurity),
                sum(LineVolume_BrokenCaseNonSecurity)
    from processLinesGroup
        group by LineCommodity, KegQtyUOM
        where processLinesGroup.KegQtyUOM  != ''
        && processLinesGroup.IsKegItem == NoYes::Yes
    {
        this.createTMSShipmentItemGroupByUOM(processLinesGroup.KegQtyUOM , processLinesTmp, processLinesGroup);
    }

    while select sum(CaseQty_CaseLines),
                sum(RepackCountSecurity),
                sum(RepackCountNonSecurity),
                sum(LineWeight_CaseLines),
                sum(LineWeight_BrokenCaseSecurity),
                sum(LineWeight_BrokenCaseNonSecurity),
                sum(LineVolume_CaseLines),
                sum(LineVolume_BrokenCaseSecurity),
                sum(LineVolume_BrokenCaseNonSecurity),
                sum(SalesQty)
    from processLinesGroup
        group by LineCommodity, IsKegItem
        where processLinesGroup.IsKegItem == NoYes::Yes
    {
        this.createTMSShipmentItemGroupByUOM(METConstants::unitPAL, processLinesTmp, processLinesGroup, NoYes::Yes);
    }

    return TSIGCreated;
}

/// <summary>
/// Step 3e: Create TMS Shipment Item Group records
/// Was previously defined in class\METTMSEngineSalesOrderProccess\createTMSShipmentItemGroupByUOM
/// </summary>
/// <param name = "_shipmentUOM">METShipmentUOM</param>
/// <param name = "_lineTmpSum">METTMSEngineSalesOrderProccessLinesTmp</param>
/// <param name = "_isKegItem">boolean</param>
protected void createTMSShipmentItemGroupByUOM(METShipmentUOM                         _shipmentUOM,
                                               METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp,
                                               METTMSEngineSalesOrderProccessLinesTmp _lineTmpSum,
                                               boolean                                _isKegItem = false)
{        
    METTMSShipmentItemGroupUOM tMSShipmentItemGroupUOM;

    // Using new refactored class to create TSIG records based on CCR or not
    tMSShipmentItemGroupUOM = METTMSShipmentItemGroupUOM::construct(_shipmentUOM,
                                                                    _processLinesTmp,
                                                                    _lineTmpSum,
                                                                    tmsShipmentOrderIdentifier,
                                                                    headerInventLocationId,
                                                                    hasCCR,
                                                                    _isKegItem,
                                                                    isToteCustomer);

    tMSShipmentItemGroupUOM.createRecord();
}
